"""Cuaderno del estudiante, 1.º medio Lengua y Literatura, OA 08 (interpretación literaria situada).

Todos los relatos y fragmentos son originales e inventados («de ejemplo»); las alusiones a mitos, cuentos tradicionales y textos
sagrados son generales y se explican en cada clase. Cada ejercicio trae escrito el texto que necesita.
Nota: los títulos de las clases del repositorio ordenan el OA en seis pasos (hipótesis, evidencias y crítica, alusiones,
contraste de hipótesis, contexto y visión de mundo, lectura propia); este cuaderno los sigue y reparte entre ellos los
contenidos del OA oficial.
"""
from __future__ import annotations

from student_content_le_m1_a import E, L, MAT, arith

OA8 = "LE1M OA 08"

# Textos originales de ejemplo
IT = ("Después de la sequía, Amalia salió al cerro con un cántaro vacío. En la cima encontró un manantial y, junto a él, un anciano que le dijo: "
      "«Puedes llevarte toda el agua, pero el manantial se secará». Amalia llenó solo medio cántaro. De vuelta, el pueblo la acusó de egoísta: «¡Había tanta agua!». "
      "Ella no respondió. Al año siguiente, el manantial seguía vivo y el pueblo, sin saber por qué, la miró distinto.")
HUE = ("Dos hermanos heredaron un huerto. El menor cultivaba flores; el mayor, papas. Cuando las flores ganaron el premio de la feria, el mayor, ciego de envidia, "
       "arrancó el rosal en la oscuridad. Al amanecer, el menor preguntó: «¿Viste quién se llevó mi rosal?». «¿Acaso me toca cuidarte?», respondió el mayor, sin mirarlo.")
PRO = ("Marisol sacó una chispa del taller cerrado de la fábrica y con ella encendió la estufa del barrio durante el invierno. Desde entonces, la empresa la declaró culpable; "
       "pero en las noches de helada, todos guardaban un trozo de brasa.")
CAP = ("La niña de la capa roja cruzó la plaza hacia la casa de su abuela. El señor del abrigo gris, que dirigía el banco, le sonrió demasiado: "
       "«¿A dónde vas tan sola?». Ella apretó la canasta y siguió caminando sin mirarlo.")
FIC = ("En el campamento minero, don Aurelio recibía su paga en fichas que solo valían en la tienda de la empresa. Una tarde, su hijo le preguntó por qué el pan costaba más allí que en el pueblo. "
       "Don Aurelio guardó las fichas en el bolsillo y dijo: «Porque aquí todo tiene dueño». Esa noche, el niño dibujó una puerta en la pared y la pintó de azul.")
BIB = ("La biblioteca del barrio cerró un jueves. Doña Ofelia guardó las llaves en el cajón donde guardaba las cartas de su esposo. Todos los días pasaba frente a la puerta y la saludaba con la cabeza, "
       "como a una vecina que se hubiera ido de viaje. Un día, un niño dejó una nota bajo la puerta: «Vuelvo mañana».")

# ------------------------------------------------------------------ OA 08 · clase 1
L(OA8, 1,
  "Aprenderé a pasar de comprender un texto a interpretarlo: formular una hipótesis sobre su sentido desde un punto de vista personal, histórico, social o universal.",
  ["Analizo narraciones, poemas y obras dramáticas.", "Distingo resumen, tema y opinión."],
  ["Interpretar un texto literario es proponer qué sentido tiene, más allá de lo que cuenta. Se formula una hipótesis de interpretación: una afirmación sobre el sentido de la obra que se puede defender con el texto. Un resumen cuenta qué pasa («Amalia lleva medio cántaro»); un tema nombra la idea general («el cuidado de los recursos»); una hipótesis afirma algo sobre el sentido («la obra muestra que cuidar lo común puede costar incomprensión»).",
   "La hipótesis puede mirar el texto desde distintos puntos de vista. Personal: lo que la obra significa para mí desde mis valores y vivencias. Histórico: lo que significa en la época en que se creó o ambientó. Social: lo que dice sobre las relaciones entre las personas o los grupos. Universal: lo que dice sobre la condición humana en cualquier tiempo. Una buena interpretación indica desde dónde habla y se apoya en citas.",
   "Una hipótesis se evalúa con tres preguntas: ¿se puede sostener con el texto?, ¿explica las partes importantes?, ¿dice algo más que el resumen? Una hipótesis como «Amalia es buena» es débil: es una opinión sin sentido global. Otra como «El texto sugiere que quien cuida lo común puede ser incomprendido hoy y valorado después» es más sólida porque integra el medio cántaro, la acusación y el final. Siempre debe quedar abierta a revisión si aparece nueva evidencia."],
  [("hipótesis de interpretación", "afirmación sobre el sentido de una obra que se defiende con el texto"), ("punto de vista personal", "lectura desde mis valores y vivencias"), ("punto de vista social", "lectura sobre las relaciones entre personas o grupos"), ("punto de vista universal", "lectura sobre la condición humana en cualquier tiempo")],
  [("Resumen, tema e hipótesis", f"Texto de ejemplo: «{IT}» Clasifica: 1) «Amalia lleva medio cántaro y el pueblo la acusa», 2) «El cuidado de los recursos», 3) «Cuidar lo común puede traer incomprensión inmediata y reconocimiento tardío».",
    ["La primera frase cuenta hechos: es un resumen.", "La segunda nombra una idea general: es un tema.", "La tercera afirma un sentido defendible: es una hipótesis."],
    "1 es resumen, 2 es tema y 3 es hipótesis"),
   ("Puntos de vista", f"Texto de ejemplo: «{IT}» Hipótesis A: «Para mí, muestra lo que me cuesta ser coherente cuando nadie entiende mis razones». Hipótesis B: «Muestra cómo una comunidad juzga sin conocer las razones». ¿Qué punto de vista predomina en cada una?",
    ["A habla desde la experiencia propia de quien lee: es personal.", "B habla de cómo se relaciona una comunidad con una persona: social.", "A es personal y B es social."],
    "A: personal; B: social")],
  [("Contar la historia y creer que eso es interpretar.", "Se confunde resumen con hipótesis.", "Agrega una afirmación sobre el sentido que se pueda defender con el texto."),
   ("Dar una opinión sin apoyo en el texto.", "Se confunde interpretar con opinar.", "Pregúntate qué parte del texto respalda tu afirmación.")],
  ([E("Un resumen... A) cuenta qué pasa B) afirma un sentido global", "A) cuenta qué pasa", "Se limita a los hechos."),
    E("Una hipótesis de interpretación es... A) una afirmación sobre el sentido que se defiende con el texto B) un dato biográfico", "A) una afirmación sobre el sentido que se defiende con el texto", "Se puede revisar si aparece nueva evidencia."),
    E("El tema de una obra es... A) la idea general B) una cita", "A) la idea general", "Es más amplio que una hipótesis.")],
   [E(f"Texto de ejemplo: «{IT}» ¿Cuál es un resumen? A) «Amalia llena medio cántaro y el pueblo la acusa de egoísta» B) «La obra critica la ingratitud humana»", "A) «Amalia llena medio cántaro y el pueblo la acusa de egoísta»", "Cuenta hechos sin afirmar un sentido."),
    E(f"Texto de ejemplo: «{IT}» ¿Cuál es una hipótesis de interpretación? A) «El texto muestra que cuidar lo común puede costar incomprensión» B) «Amalia sube al cerro»", "A) «El texto muestra que cuidar lo común puede costar incomprensión»", "Afirma un sentido apoyado en el relato."),
    E("El punto de vista histórico mira la obra desde... A) la época en que se creó o se ambientó B) las vivencias de quien lee", "A) la época en que se creó o se ambientó", "Considera el contexto temporal.")],
   [E(f"Texto de ejemplo: «{IT}» Hipótesis: «El pueblo juzga lo que ve y no lo que sucederá». ¿Qué punto de vista predomina? A) social B) histórico", "A) social", "Habla de cómo una comunidad juzga."),
    E(f"Texto de ejemplo: «{IT}» ¿Qué cita respalda la hipótesis «El pueblo juzga lo que ve»? A) «el pueblo la acusó de egoísta» B) «Después de la sequía»", "A) «el pueblo la acusó de egoísta»", "Muestra un juicio inmediato."),
    E("Un lector afirma: «Para mí, la historia significa que hay que decidir según lo que uno cree correcto, aunque cueste». ¿Qué punto de vista es? A) personal B) universal solamente", "A) personal", "Parte de sus propios valores.")],
   [E(f"Texto de ejemplo: «{IT}» ¿Cuál hipótesis es más sólida? A) «El texto sugiere que quien cuida lo común puede ser incomprendido hoy y reconocido después» B) «Amalia es buena»", "A) «El texto sugiere que quien cuida lo común puede ser incomprendido hoy y reconocido después»", "Integra varias partes del relato."),
    E(f"Texto de ejemplo: «{IT}» Un lector dice: «El anciano es el villano». ¿Qué problema tiene? A) no tiene respaldo en el texto: el anciano no hace daño B) no menciona al pueblo", "A) no tiene respaldo en el texto: el anciano no hace daño", "Solo advierte lo que ocurriría."),
    E("¿Cuál de estas afirmaciones es la más sólida como interpretación? 1) «Me gusta el cuento», 2) «Amalia sube al cerro», 3) «El cuento muestra que lo justo no siempre es entendido». Escribe el número.", "3", "Afirma un sentido y puede sostenerse.")],
   [E(f"Texto de ejemplo: «{IT}» Hipótesis universal: «La obra dice que hacer lo correcto no siempre trae reconocimiento inmediato». ¿Qué parte del relato la respalda? A) «Al año siguiente… el pueblo la miró distinto» B) «con un cántaro vacío»", "A) «Al año siguiente… el pueblo la miró distinto»", "El reconocimiento llega después."),
    E("Un estudiante escribe: «Mi hipótesis es que la historia trata de agua». ¿Qué falta? A) un sentido más allá del tema B) más agua", "A) un sentido más allá del tema", "Eso es un tema, no una hipótesis.")],
   [E(f"Texto de ejemplo: «{IT}» ¿Qué parte del texto no podría explicar la hipótesis «Amalia actuó por egoísmo»? A) «Amalia llenó solo medio cántaro» B) «el pueblo la acusó de egoísta»", "A) «Amalia llenó solo medio cántaro»", "Contradice la idea: se llevó menos de lo que podía."),
    E("Si una nueva evidencia contradice tu hipótesis, ¿qué debes hacer? A) revisarla o ajustarla B) ignorarla", "A) revisarla o ajustarla", "Una hipótesis debe quedar abierta a revisión.")]),
  [E("Texto de ejemplo: «Mateo guardó la mitad de su colación para el perro del barrio; sus compañeros se rieron de él. Semanas después, el perro lo siguió hasta la puerta del colegio y no se separó de él». ¿Cuál es una hipótesis de interpretación? A) «El texto muestra que el cuidado silencioso se paga con lealtad» B) «Mateo tiene un perro»", "A) «El texto muestra que el cuidado silencioso se paga con lealtad»", "Afirma un sentido apoyado en el relato.")],
  [E("El punto de vista social mira... A) las relaciones entre personas o grupos B) solo la vida del autor", "A) las relaciones entre personas o grupos", "Es su foco."),
   E("Una buena interpretación se apoya en... A) citas del texto B) la memoria del lector", "A) citas del texto", "La evidencia la sostiene."),
   E("Una opinión sin apoyo en el texto... A) no es una interpretación sólida B) siempre es válida", "A) no es una interpretación sólida", "Falta fundamento en el texto.")],
  (f"Lee el relato de ejemplo: «{IT}» Escribe: 1) un resumen en una oración, 2) un tema, 3) una hipótesis de interpretación, 4) el punto de vista de tu hipótesis y 5) una cita que la respalda.",
   "1) Amalia lleva medio cántaro del manantial y el pueblo la acusa de egoísta. 2) El cuidado de los recursos. 3) El texto muestra que quien cuida lo común puede ser incomprendido hoy y reconocido después. 4) Social. 5) «Al año siguiente, el manantial seguía vivo y el pueblo… la miró distinto».",
   ["distingue resumen, tema e hipótesis", "indica el punto de vista", "cita el texto"], ["cinco respuestas"], ["confundir resumen con hipótesis", "hipótesis sin cita"],
   "Marca en tu hipótesis el sentido y comprueba que la cita lo respalde."),
  "Piensa en una película que hayas visto y distingue su resumen, su tema y una posible hipótesis.",
  "Escribe dos hipótesis distintas para el mismo relato, una social y otra universal.")

# ------------------------------------------------------------------ OA 08 · clase 2
L(OA8, 2,
  "Aprenderé a sustentar una interpretación y una crítica de la obra con citas y ejemplos, integrándolos en mi texto y explicándolos.",
  ["Formulo una hipótesis de interpretación.", "Sé citar con comillas."],
  ["Una interpretación se sostiene con evidencias: citas del texto (frases exactas entre comillas) y ejemplos (hechos, gestos o imágenes de la obra que se resumen). Una cita se integra en una oración propia: «El pueblo reacciona con dureza: “la acusó de egoísta”». No se deja una cita suelta; se explica qué muestra. La estructura es: afirmación, cita o ejemplo, explicación.",
   "Una crítica de la obra es un juicio fundamentado sobre sus logros o límites: ¿qué hace bien?, ¿qué podría mejorar?, ¿qué efecto produce? Por ejemplo: «El final es eficaz porque no explica el cambio del pueblo y deja que el lector lo interprete». La crítica se sustenta con ejemplos del texto y con criterios como coherencia, originalidad, claridad o efecto en el lector. No basta decir «me aburrió»: hay que decir por qué, mostrando dónde.",
   "Al elegir evidencias, conviene preferir las más pertinentes: las que mejor respaldan la afirmación y que no se contradigan con otras partes. Si cito solo lo que me favorece y omito lo que me contradice, mi interpretación es débil. Además, cito lo breve: lo necesario para mostrar la idea. Y distingo lo que dice el texto («el manantial seguía vivo») de lo que yo infiero («la naturaleza premia la prudencia»)."],
  [("cita", "frase exacta del texto entre comillas"), ("ejemplo", "hecho o imagen de la obra que ilustra una idea"), ("crítica", "juicio fundamentado sobre logros o límites de una obra"), ("inferencia", "idea que se deduce del texto sin estar escrita")],
  [("Integrar una cita", f"Texto de ejemplo: «{IT}» Afirmación: «El pueblo reacciona sin conocer las razones». Integra una cita y explica.",
    ["Busco una frase que muestre la reacción.", "«el pueblo la acusó de egoísta».", "Explico: la acusa sin saber por qué Amalia se llevó solo medio cántaro."],
    "El pueblo reacciona sin conocer las razones: «la acusó de egoísta» sin saber por qué ella llenó solo medio cántaro"),
   ("Crítica sustentada", f"Texto de ejemplo: «{IT}» Formula una crítica positiva sobre el final y sustenta.",
    ["Observo el final: el manantial sigue vivo y el pueblo la mira distinto.", "No se explica el cambio del pueblo.", "Crítica: el final es eficaz porque deja que el lector interprete el cambio del pueblo."],
    "El final es eficaz porque no explica el cambio del pueblo y deja que el lector lo interprete")],
  [("Dejar una cita suelta sin explicarla.", "Se supone que la cita habla por sí sola.", "Después de citar, explica qué muestra."),
   ("Criticar con «me gustó» o «no me gustó».", "No hay criterios ni ejemplos.", "Indica qué hace bien o mal la obra y dónde se ve.")],
  ([E("Una cita se escribe... A) entre comillas, con las palabras exactas B) con otras palabras", "A) entre comillas, con las palabras exactas", "Reproduce el texto."),
    E("Una crítica fundamentada... A) explica por qué con ejemplos del texto B) solo dice si gustó", "A) explica por qué con ejemplos del texto", "Necesita criterios y evidencia."),
    E("Una inferencia es... A) una idea que se deduce del texto B) una cita", "A) una idea que se deduce del texto", "No está escrita textualmente.")],
   [E(f"Texto de ejemplo: «{IT}» ¿Qué cita respalda que Amalia tomó una decisión prudente? A) «Amalia llenó solo medio cántaro» B) «Ella no respondió»", "A) «Amalia llenó solo medio cántaro»", "Se llevó menos de lo posible."),
    E(f"Texto de ejemplo: «{IT}» ¿Qué dato respalda que el manantial se conservó? A) «el manantial seguía vivo» B) «salió al cerro»", "A) «el manantial seguía vivo»", "Es el resultado."),
    E(f"Texto de ejemplo: «{IT}» ¿Qué frase del anciano establece la condición? A) «Puedes llevarte toda el agua, pero el manantial se secará» B) «¡Había tanta agua!»", "A) «Puedes llevarte toda el agua, pero el manantial se secará»", "Es su advertencia.")],
   [E(f"Texto de ejemplo: «{IT}» Un estudiante escribe: «El relato critica la dureza del pueblo». ¿Qué cita puede respaldar esa idea? A) «la acusó de egoísta» B) «con un cántaro vacío»", "A) «la acusó de egoísta»", "El pueblo es quien acusa sin conocer las razones, lo que muestra su dureza."),
    E(f"Texto de ejemplo: «{IT}» Crítica: «El silencio de Amalia es un acierto». ¿Qué ejemplo lo sustenta? A) «Ella no respondió» B) «Después de la sequía»", "A) «Ella no respondió»", "Su silencio deja el juicio al lector."),
    E("Frase: «El relato es malo porque sí». ¿Qué falta? A) criterios y ejemplos B) más puntos", "A) criterios y ejemplos", "Una crítica necesita fundamento.")],
   [E(f"Texto de ejemplo: «{IT}» Un lector sostiene: «Amalia es egoísta». Cita: «llenó solo medio cántaro». ¿La cita respalda su idea? A) no, la contradice B) sí, porque llenó poco", "A) no, la contradice", "Llenó menos de lo posible para cuidar el manantial."),
    E("Un estudiante cita solo lo que le favorece e ignora un dato que lo contradice. ¿Qué problema tiene su interpretación? A) es débil por omitir evidencia B) es perfecta", "A) es débil por omitir evidencia", "Debe considerar todo el texto."),
    E(f"Texto de ejemplo: «{IT}» ¿Cuál es una inferencia y no una cita? A) la naturaleza recompensa la prudencia B) «el manantial seguía vivo»", "A) la naturaleza recompensa la prudencia", "Se deduce, pero no está escrita.")],
   [E(f"Texto de ejemplo: «{IT}» Elige la mejor integración de la cita: A) El pueblo juzga con rapidez: «la acusó de egoísta» sin saber sus razones. B) «la acusó de egoísta».", "A) El pueblo juzga con rapidez: «la acusó de egoísta» sin saber sus razones.", "Integra la cita en una oración y la explica."),
    E("Dos críticas. X: «El final me dejó pensando porque no explica por qué el pueblo cambió». Y: «No me gustó». ¿Cuál está fundamentada? A) X B) Y", "A) X", "Da razones y se refiere al texto.")],
   [E(f"Texto de ejemplo: «{IT}» Crítica con límite: «El pueblo aparece sin matices: todos acusan igual». ¿Qué evidencia la sustenta? A) «el pueblo la acusó de egoísta» (no hay voces distintas) B) «medio cántaro»", "A) «el pueblo la acusó de egoísta» (no hay voces distintas)", "Se muestra un grupo uniforme."),
    E("¿Qué paso completa la estructura de una explicación con evidencia: afirmación, cita o ejemplo y ...? A) explicación B) comparación", "A) explicación", "Es el tercer paso.")]),
  [E("Texto de ejemplo: «Julián se cayó tres veces en la carrera y cada vez se levantó sin mirar a la tribuna. Llegó último, pero sus compañeros lo esperaban en la meta, aplaudiendo». ¿Cuál es la mejor integración de evidencia para la idea «el esfuerzo se valora aunque no se gane»? A) Los compañeros lo esperan «aplaudiendo» pese a que llegó último, lo que muestra que valoran su esfuerzo. B) «aplaudiendo».", "A) Los compañeros lo esperan «aplaudiendo» pese a que llegó último, lo que muestra que valoran su esfuerzo.", "Integra la cita y explica su sentido.")],
  [E("¿Qué se hace después de integrar una cita? A) explicar qué muestra B) quitarla", "A) explicar qué muestra", "La cita necesita interpretación."),
   E("Una crítica fundamentada usa... A) criterios como coherencia, originalidad o efecto B) solo adjetivos", "A) criterios como coherencia, originalidad o efecto", "Permiten sostener el juicio."),
   E("¿Qué debe tener una interpretación sólida? A) evidencia pertinente B) citas largas", "A) evidencia pertinente", "Las citas deben ser las necesarias.")],
  (f"Con el relato de ejemplo «{IT}» escribe un párrafo de seis líneas con: una hipótesis, dos citas integradas y explicadas, y una crítica fundamentada sobre el relato (un acierto o un límite).",
   "El relato muestra que cuidar lo común puede traer incomprensión inmediata. Lo prueba la reacción del pueblo: «la acusó de egoísta». También la prudencia de Amalia: «llenó solo medio cántaro». Un acierto del relato es el final, que no explica por qué el pueblo «la miró distinto» y así invita al lector a interpretarlo.",
   ["hipótesis clara", "dos citas integradas", "crítica fundamentada"], ["párrafo de seis líneas"], ["citas sueltas", "crítica sin ejemplo"],
   "Subraya las dos citas y la crítica; comprueba que cada una tenga su explicación."),
  "Escribe una crítica fundamentada de un capítulo de una serie o un libro que conozcas, con un ejemplo.",
  "Escribe una integración de cita para esta idea: «Amalia escucha la advertencia del anciano».")

# ------------------------------------------------------------------ OA 08 · clase 3
L(OA8, 3,
  "Aprenderé a reconocer y explicar la presencia o alusión a personajes, temas o símbolos de mitos, leyendas, cuentos folclóricos y textos sagrados en una obra.",
  ["Interpreto con evidencia y cito.", "Conozco algunos mitos y cuentos tradicionales."],
  ["Muchas obras dialogan con relatos antiguos: mitos (relatos sobre dioses, héroes y el origen del mundo), leyendas (relatos tradicionales con base en hechos o lugares), cuentos folclóricos (relatos populares transmitidos oralmente, como Caperucita Roja) y textos sagrados (como la Biblia, que contiene historias como la de Caín y Abel). Estas alusiones activan en el lector ideas ya conocidas: la envidia entre hermanos, el robo del fuego, el lobo que engaña, el orgullo de la torre de Babel (una torre que quiso llegar al cielo y terminó en confusión de lenguas), el arca de Noé (la embarcación que salvó a los animales del diluvio) o el reflejo de Narciso (el joven del mito que se enamoró de su imagen en el agua).",
   "Para analizar una alusión: primero se reconoce a qué relato remite (¿qué personaje, tema o símbolo es?); segundo, se recuerda su sentido en el relato original; tercero, se observa qué hace la obra nueva con él (lo repite, lo cambia, lo ironiza) y qué sentido agrega. En el huerto de los hermanos, la envidia del mayor y la frase «¿Acaso me toca cuidarte?» recuerdan la historia de Caín y Abel, donde un hermano mata a otro por envidia y luego dice que no es el guardián de su hermano.",
   "No toda coincidencia es una alusión. Para afirmarla hay que mostrar rasgos suficientes del relato original. Y conviene cuidar la lectura de los textos sagrados: se estudian como obras literarias y como parte de la herencia cultural, sin discutir creencias. Una buena interpretación explica qué ganamos al reconocer la alusión: nuevos sentidos, una crítica o un efecto de ironía."],
  [("mito", "relato tradicional sobre dioses, héroes o el origen de algo"), ("leyenda", "relato tradicional, a veces ligado a un lugar o a hechos"), ("cuento folclórico", "relato popular transmitido de generación en generación"), ("alusión", "referencia breve a un relato o personaje conocido")],
  [("Reconocer una alusión bíblica", f"Texto de ejemplo: «{HUE}» ¿A qué relato tradicional remite y por qué?",
    ["Hay dos hermanos y una envidia que lleva a un daño.", "El mayor pregunta si le toca cuidar al menor.", "Recuerda la historia de Caín y Abel."],
    "A la historia de Caín y Abel: envidia entre hermanos y la pregunta por el cuidado del otro"),
   ("Alusión a un mito", f"Texto de ejemplo: «{PRO}» ¿A qué mito remite y qué sentido añade?",
    ["Marisol roba una chispa para dar calor a otros.", "El mito de Prometeo cuenta que robó el fuego para dárselo a los humanos y fue castigado.", "Añade la idea de que quien comparte un bien es castigado por el poder."],
    "Al mito de Prometeo; sugiere que compartir un bien puede ser castigado por quien lo controla")],
  [("Ver alusiones en cualquier parecido superficial.", "Se afirma sin rasgos suficientes.", "Muestra al menos dos rasgos del relato original en el texto."),
   ("Nombrar la alusión sin explicar qué sentido agrega.", "Se queda en el reconocimiento.", "Explica qué hace la obra nueva con el relato antiguo.")],
  ([E("Un mito es... A) un relato tradicional sobre dioses, héroes o el origen de algo B) una noticia reciente", "A) un relato tradicional sobre dioses, héroes o el origen de algo", "Es una forma de relato antiguo."),
    E("Caperucita Roja es un ejemplo de... A) cuento folclórico B) mito", "A) cuento folclórico", "Se transmitió de generación en generación."),
    E("Una alusión es... A) una referencia breve a algo conocido B) un resumen completo", "A) una referencia breve a algo conocido", "No reproduce todo el relato.")],
   [E(f"Texto de ejemplo: «{HUE}» ¿Qué sentimiento lleva al mayor a arrancar el rosal? A) la envidia B) la gratitud", "A) la envidia", "Lo dice el texto."),
    E(f"Texto de ejemplo: «{CAP}» ¿Qué cuento folclórico se evoca? A) Caperucita Roja B) Los tres cerditos", "A) Caperucita Roja", "Hay una niña de capa roja con una canasta."),
    E(f"Texto de ejemplo: «{PRO}» ¿Qué elemento recuerda al mito de Prometeo? A) una chispa o brasa sacada de un taller cerrado B) el invierno", "A) una chispa o brasa sacada de un taller cerrado", "Prometeo robó el fuego.")],
   [E(f"Texto de ejemplo: «{CAP}» ¿Quién ocupa el lugar del lobo? A) el señor del abrigo gris que dirige el banco B) la abuela", "A) el señor del abrigo gris que dirige el banco", "Le sonríe demasiado y la aborda."),
    E(f"Texto de ejemplo: «{CAP}» ¿Qué sentido agrega la reescritura? A) sugiere que el peligro puede estar en una figura de poder de la ciudad B) que el bosque es seguro", "A) sugiere que el peligro puede estar en una figura de poder de la ciudad", "Cambia el lobo por un banquero."),
    E(f"Texto de ejemplo: «{HUE}» ¿Qué frase evoca a Caín? A) «¿Acaso me toca cuidarte?» B) «Dos hermanos heredaron un huerto»", "A) «¿Acaso me toca cuidarte?»", "Recuerda su respuesta sobre el cuidado del hermano.")],
   [E(f"Texto de ejemplo: «{HUE}» Un lector dice: «El texto repite exactamente la historia de Caín». ¿Qué respuesta es adecuada? A) la adapta: no hay muerte, pero sí envidia y daño al hermano B) la copia entera", "A) la adapta: no hay muerte, pero sí envidia y daño al hermano", "Mantiene rasgos centrales con cambios."),
    E("Un lector dice: «Todo relato con dos hermanos alude a Caín y Abel». ¿Qué crítica merece? A) hacen falta rasgos suficientes, como la envidia y el daño B) tiene razón", "A) hacen falta rasgos suficientes, como la envidia y el daño", "Dos hermanos no bastan."),
    E(f"Texto de ejemplo: «{PRO}» ¿Qué efecto tiene el final «todos guardaban un trozo de brasa»? A) sugiere que el bien compartido sobrevive al castigo B) indica que la estufa se apagó", "A) sugiere que el bien compartido sobrevive al castigo", "La brasa sigue en manos de todos.")],
   [E("Texto de ejemplo: «Cuando la torre llegó al cielo, nadie entendía lo que decía el otro». ¿Qué relato sagrado puede evocar? A) la torre de Babel B) el arca de Noé", "A) la torre de Babel", "Es la historia de una torre y de lenguas que no se entienden."),
    E("Texto de ejemplo: «Salvó a los animales de la crecida construyendo una embarcación enorme». ¿Qué relato sagrado puede evocar? A) el arca de Noé B) la torre de Babel", "A) el arca de Noé", "Recuerda el barco que salvó a los animales del diluvio.")],
   [E(f"Texto de ejemplo: «{PRO}» Lectura: «Marisol es una Prometeo del barrio». ¿Qué debe mostrar quien sostiene la lectura? A) rasgos comunes con el mito, como robar un bien para compartirlo y ser castigado B) que Marisol se llama como el héroe", "A) rasgos comunes con el mito, como robar un bien para compartirlo y ser castigado", "La alusión se prueba con rasgos."),
    E("Escribe el nombre del personaje mítico que robó el fuego para los humanos.", "Prometeo", "Es el personaje del mito que se alude.")]),
  [E("Texto de ejemplo: «El niño que nunca mintió se miraba en el pozo y su reflejo le sonreía. Cuando mintió por primera vez, el reflejo desapareció». ¿Qué relación puede tener con el mito de Narciso? A) invierte el motivo del reflejo: el niño se mira y el reflejo responde a su conducta B) lo copia exactamente", "A) invierte el motivo del reflejo: el niño se mira y el reflejo responde a su conducta", "Usa el motivo del reflejo con otro sentido.")],
  [E("Una leyenda es... A) un relato tradicional, a veces ligado a un lugar B) un poema moderno", "A) un relato tradicional, a veces ligado a un lugar", "Se transmite de generación en generación."),
   E("Reconocer una alusión permite... A) descubrir sentidos nuevos B) evitar leer", "A) descubrir sentidos nuevos", "Enriquece la interpretación."),
   E("Un texto sagrado se estudia en literatura como... A) obra literaria y herencia cultural B) objeto de burla", "A) obra literaria y herencia cultural", "Se aborda con respeto y análisis.")],
  (f"Lee los relatos de ejemplo «{HUE}», «{PRO}» y «{CAP}». Elige uno y escribe cinco líneas: a qué relato remite, dos rasgos que lo prueban, qué cambia la obra nueva y qué sentido agrega.",
   "Elijo el relato de la niña de la capa roja: remite a Caperucita Roja. Los rasgos: la niña de capa roja con una canasta y un personaje que la aborda con una sonrisa excesiva. La obra cambia el lobo por el director de un banco. Agrega la idea de que el peligro puede venir de personas con poder en la ciudad.",
   ["identifica el relato", "dos rasgos", "explica el cambio y el sentido"], ["cinco líneas"], ["alusión sin rasgos", "no explicar el sentido"],
   "Subraya los dos rasgos y comprueba que expliquen la alusión."),
  "Pregunta a alguien qué cuento tradicional recuerda y qué enseñanza tenía.",
  "Escribe tres líneas de ejemplo que reescriban un cuento folclórico en un escenario actual.")

# ------------------------------------------------------------------ OA 08 · clase 4
H1 = "Hipótesis 1: «La obra defiende el cuidado de los bienes comunes aunque cueste ser incomprendido»."
H2 = "Hipótesis 2: «La obra critica la falta de empatía de una comunidad que juzga sin conocer razones»."
H3 = "Hipótesis 3: «La obra muestra que el anciano es un engañador que castiga a Amalia»."
L(OA8, 4,
  "Aprenderé a contrastar hipótesis distintas sobre un mismo texto y a evaluar cuál es más coherente con el análisis y con la totalidad de la obra.",
  ["Formulo y sustento hipótesis de interpretación.", "Reconozco alusiones."],
  ["Un mismo texto puede admitir hipótesis distintas. Contrastarlas consiste en ponerlas lado a lado y evaluarlas con criterios. Cuatro criterios útiles son: evidencia (¿se apoya en citas concretas?), coherencia (¿no contradice ninguna parte importante del texto?), alcance (¿explica varios elementos o solo uno?) y claridad (¿se entiende con precisión qué afirma?). Una hipótesis puede ser débil en un criterio y fuerte en otro.",
   "Dos hipótesis pueden ser compatibles aunque pongan el acento en cosas distintas. En el relato de Amalia, una dice que la obra defiende el cuidado de lo común; otra, que critica la falta de empatía del pueblo. Ambas se apoyan en el medio cántaro y en la acusación; pueden complementarse. En cambio, la hipótesis de que el anciano engaña a Amalia contradice el texto: el manantial sigue vivo, es decir, la advertencia era cierta.",
   "Contrastar no es buscar un ganador a toda costa. Puede concluirse que una hipótesis es más sólida; que dos se complementan; o que ninguna explica una parte relevante y hay que reformular. Lo importante es justificar la evaluación con el texto. También se reconoce lo que no se puede afirmar: si el texto no dice por qué el pueblo cambió su mirada, cualquier explicación detallada es una suposición."],
  [("coherencia", "ausencia de contradicción con el texto"), ("alcance", "cantidad de elementos del texto que una hipótesis explica"), ("compatible", "que puede sostenerse a la vez que otra"), ("reformular", "volver a plantear una idea con ajustes")],
  [("Evaluar con criterios", f"Texto de ejemplo: «{IT}» {H1} {H3} ¿Cuál es más coherente y por qué?",
    ["Reviso si cada una contradice el texto.", "La hipótesis 3 afirma que el anciano engaña; sin embargo el manantial sigue vivo, lo que confirma su advertencia.", "La hipótesis 1 es más coherente."],
    "La hipótesis 1: la 3 contradice que el manantial siga vivo"),
   ("Hipótesis compatibles", f"Texto de ejemplo: «{IT}» {H1} {H2} ¿Son compatibles?",
    ["La primera pone el acento en la acción de Amalia.", "La segunda lo pone en la reacción del pueblo.", "Ambas pueden sostenerse a la vez."],
    "Sí, se complementan: una mira a Amalia y la otra al pueblo")],
  [("Elegir una hipótesis sin revisar contradicciones.", "Se decide por gusto.", "Evalúa coherencia con todo el texto."),
   ("Creer que si hay dos hipótesis una debe ser falsa.", "No se considera la compatibilidad.", "Pregunta si ambas pueden sostenerse con la misma evidencia.")],
  ([E("La coherencia de una hipótesis es... A) no contradecir el texto B) ser corta", "A) no contradecir el texto", "Es uno de los criterios."),
    E("El alcance de una hipótesis es... A) la cantidad de elementos del texto que explica B) la cantidad de palabras", "A) la cantidad de elementos del texto que explica", "Se mide por lo que abarca."),
    E("Dos hipótesis compatibles son aquellas que... A) pueden sostenerse a la vez B) se contradicen", "A) pueden sostenerse a la vez", "No se excluyen.")],
   [E(f"Texto de ejemplo: «{IT}» {H3} ¿Qué dato del texto la contradice? A) «el manantial seguía vivo» B) «salió al cerro»", "A) «el manantial seguía vivo»", "Confirma que la advertencia era cierta."),
    E(f"Texto de ejemplo: «{IT}» {H2} ¿Qué cita la respalda? A) «el pueblo la acusó de egoísta» B) «Después de la sequía»", "A) «el pueblo la acusó de egoísta»", "Muestra el juicio sin conocer razones."),
    E(f"Texto de ejemplo: «{IT}» {H1} ¿Qué cita la respalda? A) «Amalia llenó solo medio cántaro» B) «¡Había tanta agua!»", "A) «Amalia llenó solo medio cántaro»", "Muestra una acción de cuidado.")],
   [E(f"Texto de ejemplo: «{IT}» {H1} {H2} ¿Qué hipótesis se centra en la reacción del pueblo ante Amalia? A) la 2, porque habla de cómo juzga la comunidad B) la 1, porque habla de cómo juzga la comunidad", "A) la 2, porque habla de cómo juzga la comunidad", "Se centra en la reacción del pueblo."),
    E(f"Texto de ejemplo: «{IT}» {H1} {H3} ¿Cuál tiene mayor alcance? A) la 1, porque explica el medio cántaro, la acusación y el final B) la 3", "A) la 1, porque explica el medio cántaro, la acusación y el final", "Integra más partes."),
    E("Dos lectores. X: «Es una crítica al pueblo». Y: «Es una defensa de Amalia». ¿Cómo pueden relacionarse? A) como lecturas compatibles de un mismo hecho B) como una contradicción absoluta", "A) como lecturas compatibles de un mismo hecho", "Critican y defienden desde ángulos que se complementan.")],
   [E("Un estudiante dice: «Mi hipótesis es la única válida». ¿Qué crítica merece? A) ignora que otras pueden sostenerse con evidencia B) está bien argumentada", "A) ignora que otras pueden sostenerse con evidencia", "Los textos literarios admiten más de una lectura."),
    E(f"Texto de ejemplo: «{IT}» Hipótesis nueva: «El pueblo cambió de mirada porque vio que el manantial seguía vivo». ¿Qué parte es una inferencia? A) la causa del cambio, porque el texto dice «sin saber por qué» B) que el manantial seguía vivo", "A) la causa del cambio, porque el texto dice «sin saber por qué»", "El texto no explica por qué cambió la mirada."),
    E("Si una hipótesis explica solo un detalle y deja fuera el resto, ¿qué criterio falla? A) el alcance B) la claridad", "A) el alcance", "No integra otros elementos.")],
   [E("¿Cuál de estas afirmaciones es la más sólida? 1) «Amalia es tonta», 2) «El texto muestra el costo social de cuidar lo común», 3) «Amalia sube al cerro». Escribe el número.", "2", "Es la única que afirma un sentido apoyado en el texto."),
    E(f"Texto de ejemplo: «{IT}» ¿Qué puede hacer un lector si dos hipótesis parecen válidas? A) combinarlas en una más amplia B) borrar una al azar", "A) combinarlas en una más amplia", "Integra la evidencia de ambas.")],
   [E(f"Texto de ejemplo: «{IT}» Hipótesis combinada: «El relato defiende cuidar lo común y critica a una comunidad que juzga sin conocer razones». ¿Qué par de citas la respalda? A) «llenó solo medio cántaro» y «la acusó de egoísta» B) «salió al cerro» y «un anciano»", "A) «llenó solo medio cántaro» y «la acusó de egoísta»", "Cada cita apoya una mitad de la hipótesis."),
    E("¿Qué criterio se refiere a no contradecir el texto? A) coherencia B) alcance", "A) coherencia", "Es el criterio de no contradicción.")]),
  [E(f"Texto de ejemplo: «Un niño regaló su bicicleta a otro que no tenía; su padre lo regañó, pero semanas después el otro niño le enseñó a reparar una cadena». Hipótesis X: «La obra defiende la generosidad». Hipótesis Y: «La obra muestra que la generosidad se devuelve de formas inesperadas». ¿Cuál tiene mayor alcance? A) Y, porque incluye la regañina y el aprendizaje posterior B) X", "A) Y, porque incluye la regañina y el aprendizaje posterior", "Explica más partes del relato.")],
  [E("La compatibilidad entre hipótesis significa que... A) ambas pueden sostenerse a la vez B) una anula a la otra", "A) ambas pueden sostenerse a la vez", "Ambas lecturas se complementan."),
   E("Reformular una hipótesis es... A) plantearla de nuevo con ajustes B) abandonar el texto", "A) plantearla de nuevo con ajustes", "Mejora su ajuste al texto."),
   E("Para evaluar una hipótesis se usa... A) evidencia, coherencia, alcance y claridad B) la cantidad de adjetivos", "A) evidencia, coherencia, alcance y claridad", "Son criterios útiles.")],
  (f"Con el relato de ejemplo «{IT}» y las tres hipótesis ({H1} {H2} {H3}) escribe una tabla de cuatro criterios (evidencia, coherencia, alcance, claridad) para las dos hipótesis más sólidas y una conclusión de dos líneas sobre si se pueden combinar.",
   "Hipótesis 1: evidencia «llenó solo medio cántaro»; coherente; explica la acción y el final; clara. Hipótesis 2: evidencia «la acusó de egoísta»; coherente; explica la reacción y el cambio de mirada; clara. Conclusión: son compatibles y se pueden combinar: el relato defiende cuidar lo común y critica a quienes juzgan sin conocer razones.",
   ["usa los cuatro criterios", "evalúa con el texto", "concluye sobre la combinación"], ["tabla y dos líneas"], ["evaluar sin criterio", "ignorar contradicciones"],
   "Comprueba que cada criterio tenga un dato del relato."),
  "Conversa con alguien sobre un libro o película y compara dos lecturas distintas que hayan surgido.",
  "Escribe dos hipótesis compatibles sobre el relato de la clase y explica por qué lo son.")

# ------------------------------------------------------------------ OA 08 · clase 5
L(OA8, 5,
  "Aprenderé a relacionar una obra con la visión de mundo y el contexto histórico en que se ambienta o fue creada, ejemplificando esa relación con el texto.",
  ["Interpreto, sustento y contrasto hipótesis.", "Sé que las obras reflejan su época."],
  ["La visión de mundo es el conjunto de ideas, valores y creencias que caracterizan a una época, una sociedad o una obra: qué se considera justo, normal o posible. El contexto histórico es el conjunto de hechos y condiciones de la época en que se ambienta o se escribió una obra: economía, relaciones de trabajo, formas de vida. Relacionar ambos permite entender por qué una obra muestra lo que muestra.",
   "En el relato del campamento minero, el hecho de que don Aurelio cobre en fichas que solo valen en la tienda de la empresa muestra una relación de dependencia entre trabajadores y empleador. (Dato de contexto: en algunos lugares y épocas se pagó a los trabajadores con fichas de ese tipo.) Su frase «Porque aquí todo tiene dueño» expresa la visión de mundo de quien siente que no controla su vida. La puerta azul que dibuja el niño simboliza la esperanza de salir de esa situación.",
   "Para ejemplificar la relación se sigue el esquema: contexto, elemento del texto, visión de mundo. Por ejemplo: «En un contexto de dependencia económica (contexto), el texto muestra fichas que solo valen en una tienda (elemento), lo que revela un mundo donde el trabajador no elige (visión de mundo)». Se evita inventar fechas o hechos: se usa lo que el texto da y lo que se conoce con certeza. Y se reconoce que una obra puede cuestionar la visión de su época, no solo reflejarla."],
  [("visión de mundo", "ideas y valores de una época o sociedad sobre lo justo y lo posible"), ("contexto histórico", "condiciones y hechos de la época en que se ambienta o escribe una obra"), ("dependencia", "situación en que alguien necesita de otro y no puede elegir libremente"), ("ejemplificar", "mostrar una idea con un caso concreto del texto")],
  [("Contexto, elemento y visión", f"Texto de ejemplo: «{FIC}» Relaciona un elemento con la visión de mundo.",
    ["Contexto: dependencia económica del campamento.", "Elemento del texto: las fichas que solo valen en la tienda de la empresa.", "Visión de mundo: un mundo donde el trabajador no elige y «todo tiene dueño»."],
    "Las fichas muestran dependencia; la frase «aquí todo tiene dueño» revela un mundo donde el trabajador no elige"),
   ("Símbolo y esperanza", f"Texto de ejemplo: «{FIC}» ¿Qué sentido tiene la puerta azul que dibuja el niño?",
    ["Una puerta permite salir de un lugar.", "El niño la dibuja después de entender la situación.", "Simboliza el deseo de otra vida."],
    "El deseo de salir de esa situación y empezar otra vida")],
  [("Inventar fechas o hechos para explicar el contexto.", "Se agregan datos inseguros.", "Usa lo que dice el texto y lo que conoces con certeza."),
   ("Pensar que la obra solo refleja su época.", "Se ignora que puede cuestionarla.", "Pregunta si el texto acepta o critica lo que muestra.")],
  ([E("La visión de mundo es... A) las ideas y valores de una época o sociedad B) el título de la obra", "A) las ideas y valores de una época o sociedad", "Explica lo que se considera justo o normal."),
    E("El contexto histórico incluye... A) condiciones y hechos de la época B) solo la biografía del autor", "A) condiciones y hechos de la época", "Rodea la obra."),
    E("La dependencia es... A) la situación de quien necesita a otro y no elige libremente B) la independencia", "A) la situación de quien necesita a otro y no elige libremente", "Limita la libertad.")],
   [E(f"Texto de ejemplo: «{FIC}» ¿En qué cobra su paga don Aurelio? A) en fichas B) en billetes", "A) en fichas", "Lo dice el texto."),
    E(f"Texto de ejemplo: «{FIC}» ¿Qué le pregunta el hijo? A) por qué el pan cuesta más en la tienda de la empresa B) por qué llueve", "A) por qué el pan cuesta más en la tienda de la empresa", "Es su pregunta."),
    E(f"Texto de ejemplo: «{FIC}» ¿Qué dibuja el niño? A) una puerta azul B) un camino", "A) una puerta azul", "Lo hace por la noche.")],
   [E(f"Texto de ejemplo: «{FIC}» ¿Qué frase revela la visión de mundo de don Aurelio? A) «Porque aquí todo tiene dueño» B) «guardó las fichas en el bolsillo»", "A) «Porque aquí todo tiene dueño»", "Expresa que no controla nada."),
    E(f"Texto de ejemplo: «{FIC}» Esquema contexto-elemento-visión: contexto: dependencia económica; elemento: las fichas; ¿visión de mundo? A) un mundo donde el trabajador no elige B) un mundo de libre elección", "A) un mundo donde el trabajador no elige", "Las fichas limitan su elección."),
    E(f"Texto de ejemplo: «{FIC}» ¿Qué sugiere la respuesta de don Aurelio sobre el precio del pan? A) que el trabajador depende de esa tienda y no puede elegir B) que el pan de esa tienda es de mala calidad", "A) que el trabajador depende de esa tienda y no puede elegir", "Dice que «aquí todo tiene dueño»: no explica el precio, pero muestra que no hay otra opción. La mala calidad no se menciona.")],
   [E(f"Texto de ejemplo: «{FIC}» Un lector dice: «El texto aprueba que la empresa pague con fichas». ¿Qué evidencia lo contradice? A) la frase amarga «aquí todo tiene dueño» y la puerta azul de esperanza B) el nombre del campamento", "A) la frase amarga «aquí todo tiene dueño» y la puerta azul de esperanza", "El texto muestra la situación con tono crítico."),
    E("Un estudiante dice: «Don Aurelio es tonto por no reclamar». ¿Qué lectura más situada se puede hacer? A) en un contexto de dependencia, reclamar tenía riesgos B) no hay lectura posible", "A) en un contexto de dependencia, reclamar tenía riesgos", "El contexto ayuda a entender sus decisiones."),
    E("Ordena según el esquema de la clase: 1) visión de mundo, 2) contexto, 3) elemento del texto. Escribe los números en el orden del esquema.", "2, 3, 1", "Primero contexto, luego elemento y finalmente visión de mundo.")],
   [E(f"Texto de ejemplo: «{FIC}» ¿Qué relación hay entre la puerta azul y la visión de mundo del texto? A) contrasta con la idea de que todo tiene dueño: expresa esperanza B) la confirma sin cambios", "A) contrasta con la idea de que todo tiene dueño: expresa esperanza", "El niño imagina una salida."),
    E("Un lector escribe: «En 1850 los mineros eran pagados con fichas en todo Chile». ¿Qué problema tiene? A) afirma una fecha y un alcance que no se pueden comprobar con el texto B) cita demasiado", "A) afirma una fecha y un alcance que no se pueden comprobar con el texto", "No debe inventarse información.")],
   [E(f"Texto de ejemplo: «{FIC}» Según la lectura simbólica, ¿qué sentimiento expresa el niño al dibujar la puerta? A) esperanza B) indiferencia", "A) esperanza", "Imagina una salida."),
    E("Si la obra mostrara que la empresa trata bien a sus trabajadores, ¿cambiaría la visión de mundo? A) sí, mostraría una relación menos dependiente B) no", "A) sí, mostraría una relación menos dependiente", "Cambiaría el contexto y su sentido.")]),
  [E("Texto de ejemplo: «En el pueblo de pescadores, los hombres salían al mar al alba y las mujeres reparaban las redes. Isabel, la hija del patrón, aprendió en secreto a navegar». ¿Qué relación hay entre contexto y visión de mundo? A) el texto muestra una división de roles y un cuestionamiento a través de Isabel B) no hay relación", "A) el texto muestra una división de roles y un cuestionamiento a través de Isabel", "Isabel desafía lo establecido.")],
  [E("Ejemplificar es... A) mostrar una idea con un caso del texto B) repetir la idea", "A) mostrar una idea con un caso del texto", "Se apoya en evidencia."),
   E("El esquema de la clase es... A) contexto, elemento y visión de mundo B) autor, título y año", "A) contexto, elemento y visión de mundo", "Ordena la relación."),
   E("Una obra puede... A) reflejar o cuestionar la visión de su época B) solo reflejarla", "A) reflejar o cuestionar la visión de su época", "Puede hacer ambas cosas.")],
  (f"Con el relato de ejemplo «{FIC}» escribe un párrafo de seis líneas con el esquema contexto, elemento y visión de mundo, e incluye una cita y una conclusión sobre si la obra refleja o cuestiona esa visión.",
   "El contexto es un campamento minero donde el trabajador depende de la empresa. El elemento es que don Aurelio cobre en fichas que solo valen en su tienda; la frase «Porque aquí todo tiene dueño» lo resume. La visión de mundo es la de un trabajador que siente que no elige. La obra no solo la refleja: la cuestiona con la puerta azul que dibuja el niño, que sugiere esperanza.",
   ["usa el esquema", "cita el texto", "concluye sobre reflejo o cuestionamiento"], ["párrafo de seis líneas"], ["datos inventados", "no concluir"],
   "Subraya contexto, elemento y visión de mundo, y la cita."),
  "Piensa en un objeto actual que muestre cómo vivimos hoy y explica qué dice de nuestra época.",
  "Escribe tres líneas de ejemplo sobre un relato ambientado en una época que conozcas con certeza.")

# ------------------------------------------------------------------ OA 08 · clase 6
L(OA8, 6,
  "Aprenderé a formular una interpretación completa y coherente con mi análisis: hipótesis, crítica con citas, alusiones y relación con el contexto, y a revisarla con una pauta.",
  ["Interpreto, sustento, reconozco alusiones, contrasto y sitúo.", "Sé revisar un texto propio."],
  ["Una interpretación completa articula varias partes: una hipótesis de sentido; evidencias (citas y ejemplos) que la sustentan; una crítica fundamentada de la obra; la relación con alguna alusión (mito, leyenda, cuento folclórico o texto sagrado) cuando existe; y la relación con la visión de mundo y el contexto. No todas las obras permiten todos los elementos: se usan los que el análisis respalda, sin forzarlos.",
   "Un esquema útil para escribir es: 1) presentación del texto y de la hipótesis; 2) desarrollo con dos o tres evidencias citadas y explicadas; 3) alusión o contexto (si corresponde); 4) crítica con un criterio; 5) cierre que retome la hipótesis. Debe ser coherente: ninguna idea contradice a otra ni al texto. Y debe distinguir lo que el texto dice de lo que se infiere.",
   "La revisión se hace con una pauta: ¿mi hipótesis afirma un sentido y no solo un tema?, ¿cada cita está integrada y explicada?, ¿mi crítica tiene un criterio y un ejemplo?, ¿la alusión o el contexto están mostrados con rasgos del texto, sin datos inventados?, ¿el cierre retoma la hipótesis? Revisar permite mejorar antes de entregar y mostrar con claridad el proceso de lectura."],
  [("interpretación completa", "texto que articula hipótesis, evidencias, crítica y contexto"), ("pauta de revisión", "lista de preguntas para evaluar y mejorar un texto"), ("articular", "unir partes de modo coherente"), ("cierre", "parte final que retoma la idea central")],
  [("Armar el esquema", f"Texto de ejemplo: «{BIB}» Propón una hipótesis y dos evidencias.",
    ["Hipótesis: el texto muestra que los espacios compartidos dejan huella en la comunidad, incluso cuando cierran.", "Evidencia 1: doña Ofelia saluda la puerta «como a una vecina que se hubiera ido de viaje».", "Evidencia 2: el niño deja la nota «Vuelvo mañana»."],
    "Hipótesis: los espacios compartidos dejan huella aun cerrados; evidencias: el saludo a la puerta y la nota «Vuelvo mañana»"),
   ("Revisar con pauta", "Borrador de ejemplo: «La biblioteca cierra. Es triste». ¿Qué falla según la pauta?",
    ["No afirma un sentido sino una emoción.", "No cita el texto.", "Falta crítica, evidencia y cierre."],
    "Falta hipótesis de sentido, citas, crítica y cierre")],
  [("Forzar todos los elementos, como una alusión que no existe.", "Se intenta cumplir una lista.", "Usa solo lo que el análisis respalda."),
   ("Entregar sin revisar.", "Se confía en que la primera versión es suficiente.", "Aplica la pauta y corrige.")],
  ([E("Una interpretación completa... A) articula hipótesis, evidencias, crítica y contexto cuando corresponde B) solo resume", "A) articula hipótesis, evidencias, crítica y contexto cuando corresponde", "Combina los elementos del análisis."),
    E("El cierre de una interpretación... A) retoma la hipótesis B) introduce otro tema", "A) retoma la hipótesis", "Da coherencia a todo el texto."),
    E("Una pauta de revisión sirve para... A) mejorar el texto antes de entregarlo B) alargarlo", "A) mejorar el texto antes de entregarlo", "Detecta lo que falta.")],
   [E(f"Texto de ejemplo: «{BIB}» ¿Cuál es una hipótesis de sentido? A) «El texto sugiere que un espacio compartido sigue presente en la comunidad aunque cierre» B) «La biblioteca cierra un jueves»", "A) «El texto sugiere que un espacio compartido sigue presente en la comunidad aunque cierre»", "Afirma un sentido sobre la obra."),
    E(f"Texto de ejemplo: «{BIB}» ¿Qué cita respalda la presencia de la biblioteca en la vida del barrio? A) «Vuelvo mañana» B) «cerró un jueves»", "A) «Vuelvo mañana»", "Un niño sigue relacionándose con ella."),
    E(f"Texto de ejemplo: «{BIB}» ¿Qué gesto de doña Ofelia muestra afecto? A) saludar la puerta con la cabeza B) guardar las llaves", "A) saludar la puerta con la cabeza", "Trata la biblioteca como a una persona querida.")],
   [E(f"Texto de ejemplo: «{BIB}» Crítica: «El final deja una esperanza abierta». ¿Qué ejemplo la sustenta? A) la nota «Vuelvo mañana» B) las cartas del esposo", "A) la nota «Vuelvo mañana»", "Deja abierta la posibilidad del regreso."),
    E(f"Texto de ejemplo: «{BIB}» ¿Qué detalle puede conectar el pasado personal con el espacio común? A) las llaves guardadas junto a las cartas del esposo B) el día jueves", "A) las llaves guardadas junto a las cartas del esposo", "Une lo íntimo y lo comunitario."),
    E("Un borrador dice: «El texto trata de una biblioteca». ¿Qué le falta a la hipótesis? A) un sentido sobre la obra B) más palabras", "A) un sentido sobre la obra", "Eso es un tema.")],
   [E(f"Texto de ejemplo: «{BIB}» Hipótesis: «Los espacios compartidos dejan huella aunque cierren». Contraste: «La obra critica el abandono de los espacios públicos». ¿Son compatibles? A) sí, porque la segunda puede explicar por qué esa huella duele B) no", "A) sí, porque la segunda puede explicar por qué esa huella duele", "Ambas lecturas se complementan."),
    E("En la pauta de revisión, ¿qué se pregunta de la alusión o contexto? A) si se muestran con rasgos del texto y sin datos inventados B) si son muy largos", "A) si se muestran con rasgos del texto y sin datos inventados", "Así se evita forzarlos."),
    E("Un estudiante incluye una alusión a un mito sin rasgos del texto. ¿Qué debe hacer? A) quitarla o fundamentarla B) dejarla igual", "A) quitarla o fundamentarla", "La pauta exige respaldo.")],
   [E(f"Texto de ejemplo: «{BIB}» ¿Qué cierre retoma mejor la hipótesis? A) Así, aun cerrada, la biblioteca sigue siendo parte de la vida del barrio, como muestran el saludo de doña Ofelia y la nota del niño. B) Fin.", "A) Así, aun cerrada, la biblioteca sigue siendo parte de la vida del barrio, como muestran el saludo de doña Ofelia y la nota del niño.", "Retoma la hipótesis y las evidencias."),
    E("Ordena las partes de la interpretación: 1) cierre, 2) hipótesis, 3) evidencias, 4) crítica. Escribe los números en el orden sugerido.", "2, 3, 4, 1", "Hipótesis, evidencias, crítica y cierre.")],
   [E("Un estudiante revisa su texto y descubre que una cita no respalda su idea. ¿Qué es lo más adecuado? A) cambiar la cita o la idea B) mantener ambas", "A) cambiar la cita o la idea", "La coherencia es obligatoria."),
    E("¿Qué palabra de la clase nombra «unir partes de modo coherente»? A) articular B) reformular", "A) articular", "Es la acción de unir los elementos.")]),
  [E(f"Texto de ejemplo: «Mi abuelo me regaló un reloj sin cuerda. Cada noche le doy cuerda y escucho cómo avanza. Así siento que él aún cuenta mis horas». Hipótesis: «El reloj conserva la presencia del abuelo». ¿Qué evidencia es la más fuerte? A) «Así siento que él aún cuenta mis horas» B) «Mi abuelo me regaló un reloj»", "A) «Así siento que él aún cuenta mis horas»", "Expresa el vínculo con claridad.")],
  [E("Una interpretación coherente... A) no contradice el texto ni sus propias ideas B) puede contradecirse", "A) no contradice el texto ni sus propias ideas", "Es una condición."),
   E("¿Qué se hace con una crítica? A) se sustenta con un criterio y un ejemplo B) se deja sin apoyo", "A) se sustenta con un criterio y un ejemplo", "Debe estar fundamentada."),
   E("La revisión se hace... A) antes de entregar B) después de que se califique", "A) antes de entregar", "Permite mejorar el texto.")],
  (f"Lee el relato de ejemplo: «{BIB}» Escribe una interpretación de 8 a 10 líneas con: hipótesis, dos citas integradas y explicadas, una crítica con criterio, una relación con el contexto o con una alusión (si no encuentras ninguna, dilo) y un cierre. Revísala con la pauta y señala qué cambiaste.",
   "Hipótesis: el texto sugiere que un espacio compartido sigue vivo en la comunidad aunque cierre. Primera evidencia: doña Ofelia saluda la puerta «como a una vecina que se hubiera ido de viaje», lo que muestra afecto. Segunda: el niño deja la nota «Vuelvo mañana», que mantiene viva la relación. Crítica: el final es eficaz porque deja abierta la esperanza sin explicarla. No encuentro una alusión clara a un mito; el contexto es un barrio que pierde un espacio común. Cierre: así, la biblioteca sigue presente en el barrio. Cambié la crítica para añadir un ejemplo.",
   ["hipótesis de sentido", "citas y crítica fundamentada", "revisa con pauta y reconoce lo que no hay"], ["interpretación de 8 a 10 líneas y nota de revisión"], ["forzar alusiones", "no retomar la hipótesis en el cierre"],
   "Marca cada parte de la pauta en tu texto."),
  "Cuenta a alguien tu interpretación de un cuento o película en tres frases y anota qué preguntó.",
  "Escribe tu propia pauta de revisión de seis preguntas para una interpretación literaria.")
